UPDATE bm_rule SET engine='COMPUTE', name='目标卡组选择', rule_type='推导', expression='单卡优先健康、证据有效且空闲无预留的 FLEX，否则 B；两卡只选 B；三/四卡只选 A；五卡及以上无目标排队。选中不等于可运行。', expr_json='{"policyVersion":"A800-v0.7","stage":"PLANNING","kind":"PLANNING","handler":"selectGroup","evaluatorVersion":"a800-m02-v1","inputs":["gpuCount","flex"],"inputNotes":{"gpuCount":"正整数，单位张","flex":"单卡时必填 healthy/evidenceFresh/held/reserved/occupied 五个布尔值，未知不得当空闲"},"outputs":["result","reasonCode","ruleVersion","targetGroup","requiresFeasibilityChecks"],"failureReasons":["QUEUE_NO_TARGET","INVALID_FACTS"],"workflowSteps":["提交决策","目标组选择"],"failureRoute":"无目标排队，不绕到其他大组","sampleFacts":{"gpuCount":1,"flex":{"healthy":true,"evidenceFresh":true,"held":false,"reserved":false,"occupied":false}},"parameters":{},"executionBoundary":"只读演练；输入来自调用方，不是可信调度证据。正式执行须由后端在同一决策快照内构造事实，不能依据此接口批准或执行。"}', version=version+1 WHERE rule_code='R-04' AND status='DRAFT' AND version=1 AND engine IS NULL AND metric_code IS NULL AND BINARY name='目标卡组选择' AND BINARY concept_code='COMPUTE_REQUEST' AND BINARY rule_type='推导' AND BINARY expression='单卡优先选择健康且空闲的灵活卡，否则选择 B 组。两卡选择 B 组，三至四卡选择 A 组，五卡及以上排队。' AND BINARY severity='中' AND BINARY owner='算力平台' AND BINARY expr_json='{"stage":"PLANNING","inputs":["requestedGpuCount","flexGroupState"],"failureReason":"QUEUE_NO_TARGET"}';


UPDATE bm_rule SET engine='COMPUTE', name='动作编排与交接前置条件', rule_type='动作', expression='只规划下一步：有效预留→通知成功→摘流成功且在途为零→停服确认并释放GPU→原子交接→启动。未知回执先核对，禁止未经停服确认交接。', expr_json='{"policyVersion":"A800-v0.7","stage":"EXECUTION","kind":"ACTION","handler":"actionGuard","evaluatorVersion":"a800-m02-v1","inputs":["step","reservationValid","notificationStatus","drainStatus","inFlightRequests","stopStatus","gpuReleased","handoverCommitted"],"inputNotes":{"step":"NOTIFY/DRAIN/STOP/HANDOVER/START_JOB；按步骤读取所需事实","reservationValid":"后端当前授权和预留是否仍有效","notificationStatus":"SUCCEEDED/FAILED/TIMED_OUT/UNKNOWN/PENDING，其他回执字段同样取值","drainStatus":"摘流回执","inFlightRequests":"未结束请求数，非负整数","stopStatus":"停服回执","gpuReleased":"节点确认资源已释放","handoverCommitted":"数据库原子交接已提交回执"},"outputs":["result","reasonCode","ruleVersion","nextAction","failureRoute","requiresTransaction"],"failureReasons":["QUEUE_CONFLICT","NOTIFY_FAILED","ABORT_INFLIGHT","INVALID_FACTS"],"workflowSteps":["NOTIFY","DRAIN","STOP","HANDOVER","START_JOB"],"failureRoute":"通知/摘流失败撤销补偿；停服未知先核对","sampleFacts":{"step":"HANDOVER","reservationValid":true,"notificationStatus":"SUCCEEDED","drainStatus":"SUCCEEDED","inFlightRequests":0,"stopStatus":"SUCCEEDED","gpuReleased":true,"handoverCommitted":false},"parameters":{},"executionBoundary":"只读演练；输入来自调用方，不是可信调度证据。正式执行须由后端在同一决策快照内构造事实，不能依据此接口批准或执行。"}', version=version+1 WHERE rule_code='R-05' AND status='DRAFT' AND version=1 AND engine IS NULL AND metric_code IS NULL AND BINARY name='抢占动作与交接' AND BINARY concept_code='COMPUTE_DEPLOYMENT' AND BINARY rule_type='约束' AND BINARY expression='先预留，再通知、摘流并等待在途请求结束。停服确认后，在同一事务中关闭原持有区间并激活新分配。' AND BINARY severity='高' AND BINARY owner='算力平台' AND BINARY expr_json='{"stage":"EXECUTION","inputs":["pendingAllocation","deployment","inFlightRequests","stopReceipt"],"failureReason":"ABORT_INFLIGHT"}';



UPDATE bm_rule SET engine='COMPUTE', name='预留事务回执检查', rule_type='约束', expression='检查实际预留事务回执：节点与组锁、重查队首与容量、每组最多一份待生效和一个未结束持有。不能用预检查成功代替数据库条件写入成功。', expr_json='{"policyVersion":"A800-v0.7","stage":"SUBMISSION","kind":"CONSTRAINT","handler":"reservationReceipt","evaluatorVersion":"a800-m02-v1","inputs":["duplicateRequest","transactionCommitted","nodeAndGroupLocked","queueHeadRechecked","capacityRechecked","pendingAllocationCount","openHoldCount","allocationId"],"inputNotes":{"duplicateRequest":"是否为已识别的重复申请","transactionCommitted":"真实事务是否提交，不是预计可以提交","nodeAndGroupLocked":"事务内是否按约定锁定节点共享容量和卡组","queueHeadRechecked":"锁内重新检查队首","capacityRechecked":"锁内重新计算容量","pendingAllocationCount":"该组待生效分配数；成功回执应为1","openHoldCount":"该组未结束持有数，允许旧部署仍持有","allocationId":"已创建预留编号，正整数"},"outputs":["result","reasonCode","ruleVersion","allocationId","receiptOnly"],"failureReasons":["DENY_DUPLICATE","QUEUE_CONFLICT","INVALID_FACTS"],"workflowSteps":["预留事务","提交回执"],"failureRoute":"冲突排队；重复申请返回原结果，由申请接口完成","sampleFacts":{"duplicateRequest":false,"transactionCommitted":true,"nodeAndGroupLocked":true,"queueHeadRechecked":true,"capacityRechecked":true,"pendingAllocationCount":1,"openHoldCount":1,"allocationId":1},"parameters":{},"executionBoundary":"只读演练；输入来自调用方，不是可信调度证据。正式执行须由后端在同一决策快照内构造事实，不能依据此接口批准或执行。"}', version=version+1 WHERE rule_code='R-07' AND status='DRAFT' AND version=1 AND engine IS NULL AND metric_code IS NULL AND BINARY name='预留与条件写入' AND BINARY concept_code='COMPUTE_ALLOCATION' AND BINARY rule_type='约束' AND BINARY expression='预留时校验队首、卡组和共享容量，每组最多一份待生效分配。待生效分配计入预留。' AND BINARY severity='高' AND BINARY owner='算力平台' AND BINARY expr_json='{"stage":"SUBMISSION","inputs":["groupHolder","pendingAllocation","capacityProjection"],"failureReason":"QUEUE_CONFLICT"}';




UPDATE bm_rule SET engine='COMPUTE', name='证据新鲜度', rule_type='校验', expression='同一 asOf 下所有证据均满足 observedAt≤asOf≤validUntil，且年龄不超过规则配置 maxAgeSeconds；未来、过期或陈旧证据不参与调度。', expr_json='{"policyVersion":"A800-v0.7","stage":"ADMISSION","kind":"VALIDATION","handler":"freshness","evaluatorVersion":"a800-m02-v1","inputs":["asOf","evidence"],"inputNotes":{"asOf":"本次演练的固定判断时间；正式调度必须由服务端生成","evidence":"非空数组，每项含 observedAt、validUntil，带时区 ISO 时间"},"outputs":["result","reasonCode","ruleVersion","asOf","maxAgeSeconds"],"failureReasons":["QUEUE_STALE_EVIDENCE","INVALID_FACTS"],"workflowSteps":["每次决策前","证据校验"],"failureRoute":"排队并等待有效观测","sampleFacts":{"asOf":"2026-11-06T10:00:00Z","evidence":[{"evidenceId":"E1","snapshotId":"S1","source":"SIMULATED_GPU","observedAt":"2026-11-06T10:00:00Z","validUntil":"2026-11-06T10:00:30Z"}]},"parameters":{"maxAgeSeconds":30},"executionBoundary":"只读演练；输入来自调用方，不是可信调度证据。正式执行须由后端在同一决策快照内构造事实，不能依据此接口批准或执行。"}', version=version+1 WHERE rule_code='R-11' AND status='DRAFT' AND version=1 AND engine IS NULL AND metric_code IS NULL AND BINARY name='证据新鲜度' AND BINARY concept_code='COMPUTE_EVIDENCE' AND BINARY rule_type='校验' AND BINARY expression='观测时间 ≤ 判定时间 ≤ 有效截止时间，且观测年龄不超过最大允许年龄。否则申请排队。' AND BINARY severity='高' AND BINARY owner='算力平台' AND BINARY expr_json='{"stage":"ADMISSION","inputs":["observedAt","validUntil","asOf","maxAge"],"failureReason":"QUEUE_STALE_EVIDENCE"}';





UPDATE bm_rule SET engine='COMPUTE', name='恢复可行性', rule_type='校验', expression='恢复原部署前检查全组卡健康，且其他部署基线+其他有效分配预留+本部署恢复基线不超容量；检查通过后才允许启动，之后仍须健康检查。', expr_json='{"policyVersion":"A800-v0.7","stage":"CLOSURE","kind":"VALIDATION","handler":"restore","evaluatorVersion":"a800-m02-v1","inputs":["groupCards","capacityBytes","otherDeploymentBytes","effectiveReservationBytes","restoreDeploymentBytes"],"inputNotes":{"groupCards":"原卡组完整成员及明确的健康值","capacityBytes":"节点可调度容量，字节","otherDeploymentBytes":"其他继续持有部署基线，字节","effectiveReservationBytes":"其他有效预留，排除正在释放的旧分配，字节","restoreDeploymentBytes":"固定恢复版本的资源基线，字节"},"outputs":["result","reasonCode","ruleVersion","projectedBytes"],"failureReasons":["RECOVERY_UNHEALTHY","RECOVERY_NO_CAPACITY","INVALID_FACTS"],"workflowSteps":["收尾恢复判定","恢复启动前"],"failureRoute":"不健康或容量不足则等待资源","sampleFacts":{"groupCards":[{"gpuId":4,"healthy":true},{"gpuId":5,"healthy":true}],"capacityBytes":{"memoryBytes":137438953472,"temporaryBytes":107374182400,"persistentBytes":1073741824000},"otherDeploymentBytes":{"memoryBytes":34359738368,"temporaryBytes":0,"persistentBytes":0},"effectiveReservationBytes":{"memoryBytes":17179869184,"temporaryBytes":0,"persistentBytes":0},"restoreDeploymentBytes":{"memoryBytes":68719476736,"temporaryBytes":0,"persistentBytes":0}},"parameters":{},"executionBoundary":"只读演练；输入来自调用方，不是可信调度证据。正式执行须由后端在同一决策快照内构造事实，不能依据此接口批准或执行。"}', version=version+1 WHERE rule_code='R-15' AND status='DRAFT' AND version=1 AND engine IS NULL AND metric_code IS NULL AND BINARY name='原部署恢复可行性' AND BINARY concept_code='COMPUTE_DEPLOYMENT' AND BINARY rule_type='校验' AND BINARY expression='恢复前检查整组 GPU 健康和恢复后的资源用量。资源不足时等待资源并重新判定。' AND BINARY severity='高' AND BINARY owner='算力平台' AND BINARY expr_json='{"stage":"CLOSURE","inputs":["groupHealth","restoreProjection"],"failureReasons":["RECOVERY_UNHEALTHY","RECOVERY_NO_CAPACITY"]}';

